import React, { useState } from "react";
import Swal from "sweetalert2";
import "bootstrap/dist/css/bootstrap.min.css";
import Plantilla from './plantilla_carga_tipologias_subtipologias.xlsx';
import config from './config';
import * as XLSX from "xlsx";

const App = () => {
  const [loaderVisible, setLoaderVisible] = useState(false);
  const [file, setFile] = useState(null);

  const getUrlParams = () => {
    const params = new URLSearchParams(window.location.search);
    const id = params.get("id");
    const campana = params.get("campana");

    if (!id || !campana) {
      throw new Error("Faltan parámetros en la URL.");
    }

    return { id, campana };
  };

  const handleTokenError = () => {
    localStorage.removeItem("token");
    Swal.fire("Error", "No estás autenticado. Por favor, inicia sesión.", "error").then(() => {
      window.location.href = "/";
    });
  };

  const decrypt = async (value) => {
    if (!value || value.trim() === "") {
      throw new Error("El valor encriptado está vacío o es inválido.");
    }

    const token = localStorage.getItem("token");
    if (!token) {
      handleTokenError();
      return;
    }

    const response = await fetch(`${config.API_BASE_URL}/decrypt`, {
      method: "POST",
      headers: {
        "Content-Type": "application/json",
        Authorization: `Bearer ${token}`,
      },
      body: JSON.stringify({ encrypted_value: value }),
    });

    if (response.status === 401) {
      handleTokenError();
      return;
    }

    if (!response.ok) {
      const errorText = await response.text();
      throw new Error(`Error al desencriptar: ${errorText}`);
    }

    const data = await response.json();
    if (!data.decrypted_value) {
      throw new Error("La API no devolvió un valor desencriptado.");
    }

    return data.decrypted_value;
  };

  const handleFileChange = (event) => {
    setFile(event.target.files[0]);
  };

  const handleDownloadTemplate = () => {
    const link = document.createElement("a");
    link.href = Plantilla;
    link.download = "plantilla_carga_tipologias_subtipologias.xlsx";
    link.click();
  };

  const renderErrorTable = (errores) => {
    const errorTable = document.createElement("table");
    errorTable.classList.add("table", "table-bordered", "mt-3");

    // Crear encabezados
    const headerRow = errorTable.insertRow();
    const headers = ["Fila", "Mensaje de Error"];
    headers.forEach((headerText) => {
      const th = document.createElement("th");
      th.textContent = headerText;
      headerRow.appendChild(th);
    });

    // Agregar filas de errores
    errores.forEach((error) => {
      const row = errorTable.insertRow();
      const cellFila = row.insertCell(0);
      const cellMensaje = row.insertCell(1);

      cellFila.textContent = error.fila;
      cellMensaje.textContent = error.mensaje;
    });

    const container = document.querySelector(".card-body");
    const existingTable = container.querySelector("table");
    if (existingTable) {
      existingTable.remove();
    }
    container.appendChild(errorTable);
  };

  const downloadErrorReport = (errores) => {
    const worksheet = XLSX.utils.json_to_sheet(errores);
    const workbook = XLSX.utils.book_new();
    XLSX.utils.book_append_sheet(workbook, worksheet, "Errores");

    // Generar archivo Excel
    const excelData = XLSX.write(workbook, { bookType: "xlsx", type: "array" });

    const blob = new Blob([excelData], { type: "application/octet-stream" });
    const link = document.createElement("a");
    link.href = URL.createObjectURL(blob);
    link.download = "reporte_errores_carga_tipologias.xlsx";
    link.click();
  };

  const handleUploadFile = async () => {
    if (!file) {
      return Swal.fire("Error", "Debe seleccionar un archivo.", "error");
    }

    if (!file.name.match(/\.(xlsx)$/i)) {
      return Swal.fire("Error", "El archivo debe ser un archivo Excel (.xlsx).", "error");
    }

    setLoaderVisible(true);

    try {
      const token = localStorage.getItem("token");
      if (!token) {
        handleTokenError();
        return;
      }

      const urlParams = getUrlParams();
      const idCampana = await decrypt(urlParams.campana);
      const usuarioOperacion = await decrypt(urlParams.id);

      const reader = new FileReader();

      reader.onerror = () => {
        setLoaderVisible(false);
        Swal.fire("Error", "Ocurrió un problema al leer el archivo. Intente nuevamente.", "error");
      };

      reader.onload = async (event) => {
        const data = new Uint8Array(event.target.result);
        let workbook;

        try {
          workbook = XLSX.read(data, { type: "array" });
        } catch (error) {
          setLoaderVisible(false);
          Swal.fire("Error", "El archivo no es un Excel válido.", "error");
          return;
        }

        const sheetName = workbook.SheetNames[0];
        const rows = XLSX.utils.sheet_to_json(workbook.Sheets[sheetName], { header: 1 });

        if (!rows || rows.length <= 1) {
          setLoaderVisible(false);
          return Swal.fire("Error", "El archivo Excel no contiene filas de datos.", "error");
        }

        const dataRows = rows.slice(1).filter((row) =>
          row.some((cell) => cell !== null && cell !== undefined && cell.toString().trim() !== "")
        );

        if (dataRows.length === 0) {
          setLoaderVisible(false);
          return Swal.fire("Error", "El archivo Excel no contiene datos válidos.", "error");
        }

        // Arreglo para almacenar errores
        const errores = [];

        // Procesar cada fila
        for (let index = 0; index < dataRows.length; index++) {
          const row = dataRows[index];
          try {
            const body = {
              id_campana: parseInt(idCampana) || null,
              id_usuario: parseInt(usuarioOperacion) || null,
              p_tipologia: row[0]?.toString() || "",
              p_sub_tipologia: row[1]?.toString() || "",
              p_razon_mora: row[2]?.toString() || "",
              p_tipo_contacto: row[3]?.toString() || "",           
            };

            const response = await fetch(`${config.API_BASE_URL}/tipologias`, {
              method: "POST",
              headers: {
                "Content-Type": "application/json",
                Authorization: `Bearer ${token}`,
              },
              body: JSON.stringify(body),
            });

            if (!response.ok) {
              if (response.status === 401) {
                handleTokenError();
                return;
              }
              const errorText = await response.text();
              throw new Error(`Error en la carga: ${errorText}`);
            }
          } catch (e) {
            // Registrar errores
            const errorMessage = e.message || e.detail || "";
            errores.push({
              fila: index + 2,
              mensaje: `Error inesperado: ${errorMessage}`
            });
          }
        }

        setLoaderVisible(false);

        // Mostrar tabla de errores
        if (errores.length > 0) {
          renderErrorTable(errores);
          downloadErrorReport(errores);
          Swal.fire("Atención", "Algunas filas tienen errores. Por favor, verifica el reporte de errores.", "warning");
        } else  {
          Swal.fire("Éxito", "Archivo procesado correctamente.", "success").then(() => {
            // Redirigir a la pestaña deseada
            const urlParams = getUrlParams();
            window.location.href = `./carga_tipologias_subtipologias?id=${urlParams.id}&campana=${urlParams.campana}`;
          });
        }
      };

      reader.readAsArrayBuffer(file);
    } catch (error) {
      setLoaderVisible(false);
      Swal.fire("Error", error.message, "error");
    }
  };

  const handleBackToPanel = () => {
    const urlParams = getUrlParams();
    window.location.href = `./modulos?id=${urlParams.id}&campana=${urlParams.campana}`;
  };

  return (
    <div className="container mt-5">
      <div className="card">
        <div className="card-header text-center">
          <h4>Carga de Tipologías</h4>
          <button className="btn btn-warning" onClick={handleBackToPanel}>
            Regresar al panel de módulos
          </button>
        </div>
        <div className="card-body">
          <div className="mb-3">
            <button className="btn btn-primary" onClick={handleDownloadTemplate}>
              Descargar Plantilla
            </button>
          </div>
          <form>
            <div className="mb-3">
              <label htmlFor="fileInput" className="form-label">
                Subir archivo Excel
              </label>
              <input type="file" className="form-control" id="fileInput" accept=".xlsx" onChange={handleFileChange} />
            </div>
            <button type="button" className="btn btn-success" onClick={handleUploadFile}>
              Cargar
            </button>
          </form>
          {loaderVisible && <div className="loader mt-3"></div>}
        </div>
      </div>
    </div>
  );
};

export default App;
